class ChiefMinister {
    String name;
    int term;

    ChiefMinister(String name, int term) {
        this.name = name;
        this.term = term;
    }
}

class ChiefMinister {
    String name;
    int term;

    private ChiefMinister(String name, int term) {
        this.name = name;
        this.term = term;
    }

    private static ChiefMinister ref;

    public static ChiefMinister getInstance(String name, int term) {
        if (ref == null) {
            ref = new ChiefMinister(name, term);
        }

        return ref;
    }
}

